sealed interface Node permits Leaf, Branch { }
record Leaf(int value) implements Node { }
record Branch(Node left, Node right) implements Node { }
public class S8 {
    static int depth(Node n) {
        return switch (n) {
            case Leaf l -> 1;
            case Branch b -> 1 + Math.max(depth(b.left()), depth(b.right()));
        };
    }
    public static void main(String[] args) {
        Node tree = new Branch(new Leaf(1), new Branch(new Leaf(2), new Branch(new Leaf(3), new Leaf(4))));
        System.out.println(depth(tree));
    }
}
